create or replace function gov_repo.agent_semantic_search(p_query_embedding vector(1536),p_organisation_id uuid,p_model_name varchar default null,p_limit integer default 10,p_similarity_threshold numeric default 0.70)
returns table(agent_id uuid,agent_code varchar,agent_name varchar,agent_type gov_repo.agent_type,risk_level gov_repo.agent_risk_level,oversight_level gov_repo.oversight_level,ai_system_id uuid,owner_name varchar,similarity numeric,content_snippet text)
language sql security definer as $$ select a.agent_id,a.agent_code,a.name,a.agent_type,a.risk_level,a.oversight_level,a.ai_system_id,u.full_name,round((1-(ae.embedding <=> p_query_embedding))::numeric,4),left(ae.content_text,300) from gov_repo.agent_embeddings ae join gov_repo.agents a on a.agent_id=ae.agent_id join gov_repo.governance_users u on u.user_id=a.owner_user_id where ae.organisation_id=p_organisation_id and ae.is_current=true and a.status in ('active','approved') and (p_model_name is null or ae.model_name=p_model_name) and (1-(ae.embedding <=> p_query_embedding))>=p_similarity_threshold order by ae.embedding <=> p_query_embedding asc limit p_limit; $$;
comment on function gov_repo.agent_semantic_search is '[C4] Semantic similarity search via pgvector cosine distance. p_model_name: STRONGLY recommended — prevents cross-model dimension mismatch. p_similarity_threshold: 0.70 = good match. 0.90 = very close. Returns ai_system_id for AI Act system-level grouping. Foundation for Talk-to-Governance NL interface (Migration 008).';
create or replace function gov_repo.agent_compliance_gaps(p_organisation_id uuid)
returns table(agent_id uuid,agent_code varchar,agent_name varchar,risk_level gov_repo.agent_risk_level,status gov_repo.agent_status,ai_system_id uuid,gap_cg_ag_001 boolean,gap_cg_ag_002 boolean,gap_cg_ag_003 boolean,gap_cg_ag_007 boolean,gap_cg_ag_010 boolean,gap_cg_ag_012 boolean,gap_no_ai_system boolean,total_gaps integer,owner_name varchar,owner_email varchar)
language sql security definer as $$ select a.agent_id,a.agent_code,a.name,a.risk_level,a.status,a.ai_system_id,not a.cg_ag_001_registered,not a.cg_ag_002_owner,not a.cg_ag_003_model_reg,not a.cg_ag_007_oversight,not a.cg_ag_010_classified,(a.agent_type='autonomous' and not a.cg_ag_012_autonomous_governed),(a.ai_system_id is null),(case when not a.cg_ag_001_registered then 1 else 0 end + case when not a.cg_ag_002_owner then 1 else 0 end + case when not a.cg_ag_003_model_reg then 1 else 0 end + case when not a.cg_ag_007_oversight then 1 else 0 end + case when not a.cg_ag_010_classified then 1 else 0 end + case when a.agent_type='autonomous' and not a.cg_ag_012_autonomous_governed then 1 else 0 end + case when a.ai_system_id is null then 1 else 0 end),u.full_name,u.email from gov_repo.agents a join gov_repo.governance_users u on u.user_id=a.owner_user_id where a.organisation_id=p_organisation_id and a.status not in ('decommissioned') and (not a.cg_ag_001_registered or not a.cg_ag_002_owner or not a.cg_ag_003_model_reg or not a.cg_ag_007_oversight or not a.cg_ag_010_classified or (a.agent_type='autonomous' and not a.cg_ag_012_autonomous_governed) or a.ai_system_id is null) order by case a.risk_level when 'critical' then 1 when 'high' then 2 when 'medium' then 3 else 4 end,14 desc; $$;
comment on function gov_repo.agent_compliance_gaps is 'CG-AGF compliance gap detector. Returns one row per non-compliant agent. [C2] gap_no_ai_system: agent not linked to an AI System (AI Act gap). [FIX-3] total_gaps uses explicit CASE WHEN for PostgreSQL version compatibility. Sorted by risk level then total gaps. Answer: "Which agents need governance attention?"';
create or replace view gov_repo.v_ciso_agent_risk_lens as select a.organisation_id,a.agent_id,a.agent_code,a.name as agent_name,a.agent_type,a.risk_level,a.ai_act_risk_class,a.oversight_level,a.status,a.deployment_env,a.model_is_local,a.ai_system_id,u.full_name as owner_name,u.email as owner_email,not a.cg_ag_001_registered as gap_inventory,not a.cg_ag_002_owner as gap_owner,not a.cg_ag_007_oversight as gap_oversight,not a.cg_ag_010_classified as gap_risk_class,(a.ai_system_id is null) as gap_no_ai_system,(select count(*) from gov_repo.agent_edges e where e.source_agent_id=a.agent_id and e.is_active=true) as outbound_edges,(select count(*) from gov_repo.agent_edges e where e.target_agent_id=a.agent_id and e.is_active=true) as inbound_edges,(select count(*) from gov_repo.agent_resource_links rl where rl.agent_id=a.agent_id and rl.processes_pii=true and rl.is_active=true) as pii_resource_count,(select count(*) from gov_repo.agent_risk_propagation rp where rp.risk_source_agent_id=a.agent_id and rp.is_active=true) as agents_it_can_impact,(select coalesce(sum(rp.financial_impact_eur),0) from gov_repo.agent_risk_propagation rp where rp.risk_source_agent_id=a.agent_id and rp.is_active=true) as total_financial_exposure_eur,(select count(*) from gov_repo.exceptions ex where ex.agent_id=a.agent_id and ex.status='active') as active_exceptions from gov_repo.agents a join gov_repo.governance_users u on u.user_id=a.owner_user_id where a.status not in ('decommissioned') and a.risk_level in ('critical','high');
comment on view gov_repo.v_ciso_agent_risk_lens is 'CISO lens: critical/high risk agents with compliance gaps, PII exposure, financial risk. [C2] gap_no_ai_system: agents not linked to AI Systems (AI Act gap).';
create or replace view gov_repo.v_risk_propagation_chains as select rp.organisation_id,rp.propagation_id,src.agent_code as source_agent_code,src.name as source_agent_name,src.risk_level as source_risk_level,src.ai_system_id as source_ai_system_id,aff.agent_code as affected_agent_code,aff.name as affected_agent_name,aff.risk_level as affected_risk_level,rp.propagation_depth,rp.propagation_type,rp.impact_score,rp.criticality,rp.financial_impact_eur,rp.propagation_path,rp.processes_impacted,rp.computed_at,u.full_name as affected_owner_name from gov_repo.agent_risk_propagation rp join gov_repo.agents src on src.agent_id=rp.risk_source_agent_id join gov_repo.agents aff on aff.agent_id=rp.affected_agent_id join gov_repo.governance_users u on u.user_id=aff.owner_user_id where rp.is_active=true and rp.criticality in ('critical','high') order by rp.impact_score desc;
create or replace view gov_repo.v_mcp_governance_lens as select rl.organisation_id,a.agent_code,a.name as agent_name,a.risk_level,a.status as agent_status,rl.resource_name as mcp_name,rl.resource_ref as mcp_ref,rl.resource_provider as mcp_provider,rl.access_type,rl.data_classification,rl.processes_pii,rl.processes_phi,rl.processes_financial,rl.data_residency,rl.cg_ag_006_compliant,rl.cg_ag_009_compliant,rl.last_reviewed_at,rl.next_review_date,rl.next_review_date<current_date as review_overdue,u.full_name as agent_owner from gov_repo.agent_resource_links rl join gov_repo.agents a on a.agent_id=rl.agent_id join gov_repo.governance_users u on u.user_id=a.owner_user_id where rl.resource_type='mcp_server' and rl.is_active=true and a.status not in ('decommissioned');
create or replace view gov_repo.v_orphan_agents as select a.organisation_id,a.agent_id,a.agent_code,a.name,a.agent_type,a.risk_level,a.status,a.ai_system_id,(a.ai_system_id is null) as missing_ai_system,a.created_at,now()-a.created_at as age_without_owner from gov_repo.agents a where a.cg_ag_002_owner=false and a.status not in ('decommissioned') order by case a.risk_level when 'critical' then 1 when 'high' then 2 else 3 end,a.created_at asc;
create or replace view gov_repo.v_agents_without_ai_system as select a.organisation_id,a.agent_id,a.agent_code,a.name,a.agent_type,a.risk_level,a.ai_act_risk_class,a.status,u.full_name as owner_name,u.email as owner_email,a.created_at from gov_repo.agents a join gov_repo.governance_users u on u.user_id=a.owner_user_id where a.ai_system_id is null and a.status not in ('decommissioned') order by case a.risk_level when 'critical' then 1 when 'high' then 2 else 3 end,a.created_at asc;;
